-- NEXIOS Modern Skills Pack 1.0.0
-- Generated 2026-07-24. Review in a non-production environment first.

CREATE TABLE IF NOT EXISTS public.skill_registry (
  id text PRIMARY KEY,
  name_ar text NOT NULL,
  name_en text NOT NULL,
  description text NOT NULL,
  category text NOT NULL,
  instructions_md text NOT NULL,
  input_contract jsonb NOT NULL DEFAULT '{}'::jsonb,
  output_contract jsonb NOT NULL DEFAULT '{}'::jsonb,
  tool_allowlist text[] NOT NULL DEFAULT '{}',
  risk_level text NOT NULL CHECK (risk_level IN ('low','medium','high')),
  enabled boolean NOT NULL DEFAULT false,
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.organization_skill_settings (
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  skill_id text NOT NULL REFERENCES public.skill_registry(id) ON DELETE CASCADE,
  enabled boolean NOT NULL DEFAULT false,
  config jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, skill_id)
);

CREATE INDEX IF NOT EXISTS skill_registry_category_enabled_idx
  ON public.skill_registry(category, enabled);
CREATE INDEX IF NOT EXISTS organization_skill_settings_enabled_idx
  ON public.organization_skill_settings(org_id, enabled)
  WHERE enabled = true;

ALTER TABLE public.skill_registry ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organization_skill_settings ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS skill_registry_read_authenticated ON public.skill_registry;
CREATE POLICY skill_registry_read_authenticated
  ON public.skill_registry FOR SELECT TO authenticated
  USING (true);

DROP POLICY IF EXISTS skill_registry_admin_write ON public.skill_registry;
CREATE POLICY skill_registry_admin_write
  ON public.skill_registry FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));

DROP POLICY IF EXISTS organization_skill_settings_read ON public.organization_skill_settings;
CREATE POLICY organization_skill_settings_read
  ON public.organization_skill_settings FOR SELECT TO authenticated
  USING (public.is_org_member(org_id, 'viewer'));

DROP POLICY IF EXISTS organization_skill_settings_write ON public.organization_skill_settings;
CREATE POLICY organization_skill_settings_write
  ON public.organization_skill_settings FOR ALL TO authenticated
  USING (public.is_org_member(org_id, 'manager'))
  WITH CHECK (public.is_org_member(org_id, 'manager'));

GRANT SELECT ON public.skill_registry TO authenticated;
GRANT SELECT ON public.organization_skill_settings TO authenticated;
GRANT ALL ON public.skill_registry TO service_role;
GRANT ALL ON public.organization_skill_settings TO service_role;

WITH pack_rows AS (
  SELECT *
  FROM jsonb_to_recordset($skills$
[{"id":"nx-build-executive-brief","name_ar":"بناء موجز تنفيذي","name_en":"Build Executive Brief","description":"Execute build executive brief for NEXIOS with evidence, tenant isolation, explicit uncertainty, and governed actions. Use when the user or an agent needs to condense live operating evidence into a decision-ready one-page brief.","category":"executive-strategy","instructions_md":"# Build Executive Brief\n\n**الاسم العربي:** بناء موجز تنفيذي  \n**المجال:** القيادة والاستراتيجية\n\n## Mission\n\nCondense live operating evidence into a decision-ready one-page brief. Work from authoritative NEXIOS evidence and return an auditable result that a human owner can verify.\n\n## Required inputs\n\n- decision objective\n- time horizon\n- trusted KPIs\n- constraints\n- decision owner\n\nBefore analysis, mark each input as verified, stale, missing, conflicting, or simulated. Record its source identifier and observation time.\n\n## Workflow\n\n1. Frame the decision, owner, deadline, and irreversible consequences.\n2. Separate verified facts, assumptions, forecasts, and stakeholder positions.\n3. Compare at least three viable options against value, risk, feasibility, and timing.\n4. Stress-test the preferred option with a pre-mortem and explicit disconfirming evidence.\n5. Produce a decision record with owner, actions, checkpoints, and leading indicators.\n6. Run a final contradiction, completeness, tenant-boundary, and approval check.\n\n## Evidence rules\n\n- Cite a source identifier and observation time for every material factual claim.\n- Separate fact, inference, forecast, recommendation, and human decision.\n- Use calibrated confidence: high, medium, low, or insufficient evidence.\n- Abstain when evidence is insufficient for a consequential conclusion.\n- Never treat simulated or demo data as production evidence.\n\n## Tool policy\n\nRecommended allowlist:\n- `nx.data.query-catalog`\n- `nx.knowledge.search-corpus`\n- `nx.governance.map-evidence`\n\nDiscover and call only tools approved for the active organization and agent. Validate input and output schemas. A tool descriptor does not prove that a connector is configured.\n\n## Approval and safety\n\n- Keep all access inside the active organization; never infer or combine cross-tenant data.\n- Request human approval before any write, notification, dispatch, account, financial, safety, or other material external action.\n- For life safety, security, legal, regulatory, medical, or financial consequences, provide decision support and route authority to the accountable human.\n- Do not bypass RLS, connector scopes, approval ledgers, rate limits, or audit logging.\n- Prefer reversible or compensating actions and state rollback criteria before execution.\n\n## Output contract\n\nReturn:\n\n1. `status`: complete, partial, blocked, or insufficient_evidence.\n2. `summary_ar`: concise Arabic-first result.\n3. `summary_en`: aligned English summary.\n4. `evidence`: source, source ID, observation time, supported claim, and confidence.\n5. `analysis`: method, comparisons, assumptions, and contradictions.\n6. `recommendations`: ranked options with benefits, risks, and dependencies.\n7. `actions`: owner, due date, approval requirement, and success measure.\n8. `confidence`: calibrated overall confidence and why.\n9. `limitations`: missing evidence, scope exclusions, and required expert review.\n\n## Completion gate\n\nComplete only when the result is reproducible from cited evidence, material uncertainty is visible, every consequential action has an owner and approval path, and no unresolved tenant or safety violation remains.\n","input_contract":{"required":["decision objective","time horizon","trusted KPIs","constraints","decision owner"],"rules":["Identify the authoritative source and observation time for each material input.","State missing, stale, conflicting, or simulated data before analysis.","Minimize personal and sensitive data to the task purpose."]},"output_contract":{"format":"structured_markdown_and_json","required":["status","summary_ar","summary_en","evidence","analysis","recommendations","actions","confidence","limitations"],"evidenceItem":["source","source_id","observed_at","claim_supported","confidence"],"actionItem":["action","owner","due_at","approval_required","success_measure"]},"tool_allowlist":["nx.data.query-catalog","nx.knowledge.search-corpus","nx.governance.map-evidence"],"risk_level":"low","enabled":false,"version":1,"metadata":{"pack":"nexios-modern-skills-pack","path":"skills/nx-build-executive-brief/SKILL.md","recommendedAgents":["nx_chief_executive_advisor","nx_strategy_portfolio_director","nx_board_briefing_director","nx_enterprise_risk_director","nx_finance_value_director","nx_governance_assurance_director","nx_legal_policy_advisor","nx_transformation_office_director","nx_decision_quality_challenger"],"sourceType":"original-derived-from-open-standards","importedAt":"2026-07-24T12:00:00+03:00"}},{"id":"nx-prepare-board-decision","name_ar":"إعداد قرار مجلس الإدارة","name_en":"Prepare Board Decision","description":"Execute prepare board decision for NEXIOS with evidence, tenant isolation, explicit uncertainty, and governed actions. Use when the user or an agent needs to prepare options, fiduciary considerations, risks, and the requested board resolution.","category":"executive-strategy","instructions_md":"# Prepare Board Decision\n\n**الاسم العربي:** إعداد قرار مجلس الإدارة  \n**المجال:** القيادة والاستراتيجية\n\n## Mission\n\nPrepare options, fiduciary considerations, risks, and the requested board resolution. Work from authoritative NEXIOS evidence and return an auditable result that a human owner can verify.\n\n## Required inputs\n\n- decision objective\n- time horizon\n- trusted KPIs\n- constraints\n- decision owner\n\nBefore analysis, mark each input as verified, stale, missing, conflicting, or simulated. Record its source identifier and observation time.\n\n## Workflow\n\n1. Frame the decision, owner, deadline, and